<?php
$adminPerPage=15;
$adminPage=max(1,(int)($_GET['page']??1));
$adminPager=function(int $page,int $pages,array $params=[]): string {
    if($pages<=1)return '';
    $base=['route'=>'dashboard','tab'=>(string)($_GET['tab']??'overview'),'as'=>'admin'];
    $link=function(int $target)use($base,$params):string{return e('index.php?'.http_build_query(array_merge($base,$params,['page'=>$target])));};
    ob_start(); ?>
    <nav class="admin-pagination" aria-label="Admin pagination">
      <span>Page <?=number_format($page)?> of <?=number_format($pages)?></span>
      <div><?php if($page>1): ?><a class="btn sm secondary" href="<?=$link($page-1)?>">Previous</a><?php endif; ?><?php if($page<$pages): ?><a class="btn sm secondary" href="<?=$link($page+1)?>">Next</a><?php endif; ?></div>
    </nav>
    <?php return (string)ob_get_clean();
};
$adminDateRange=function():array {
    $from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));
    $isDate=static function(string $value):bool {if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$value,$m))return false;return checkdate((int)$m[2],(int)$m[3],(int)$m[1]);};
    if($from!==''&&!$isDate($from))$from='';
    if($to!==''&&!$isDate($to))$to='';
    if($from!==''&&$to!==''&&$from>$to){$tmp=$from;$from=$to;$to=$tmp;}
    return [$from,$to];
};
$adminDateWhere=function(string $column,string $from,string $to):array {
    $sql='';$params=[];
    if($from!==''){$sql.=" AND {$column} >= ?";$params[]=$from.' 00:00:00';}
    if($to!==''){$sql.=" AND {$column} < DATE_ADD(?, INTERVAL 1 DAY)";$params[]=$to.' 00:00:00';}
    return [$sql,$params];
};
$adminQueryPage=function(string $countSql,string $dataSql,array $params,int $page,int $perPage)use($pdo):array {
    $count=$pdo->prepare($countSql);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
    $st=$pdo->prepare($dataSql.' LIMIT '.$perPage.' OFFSET '.$offset);$st->execute($params);return [$st->fetchAll(),$total,$pages,$page];
};
?>
