<section class="panel support-inbox-panel"><div class="panel-head"><div><span class="eyebrow">CUSTOMER SUPPORT</span><h3>Support inbox</h3><p><?=number_format($total)?> matching requests. Messages submitted from the public Contact page are stored here.</p></div><div class="admin-support-counts"><span>New <strong><?=number_format($supportCounts['new']??0)?></strong></span><span>In progress <strong><?=number_format($supportCounts['in_progress']??0)?></strong></span></div></div><div class="panel-body"><form method="get" class="admin-filter-form"><input type="hidden" name="route" value="dashboard"><input type="hidden" name="tab" value="support"><label class="admin-search"><i data-lucide="search"></i><input type="search" name="q" value="<?=e($q)?>" placeholder="Search sender, email, topic or message..."></label><select name="status"><option value="all">All statuses</option><?php foreach(['new','in_progress','resolved','closed'] as $v): ?><option value="<?=$v?>" <?=$filter===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach; ?></select><button class="btn sm">Search inbox</button><a class="btn sm secondary" href="<?=e($sideUrl('support'))?>">Reset</a></form>
